]=]},{[ [=[path]=] ]={[=[ReplicatedStorage]=],[=[Modules]=],[=[Game]=],[=[World]=],[=[LightingSchedule]=]},[ [=[source]=] ]=[=[-- Edit this ordered table to change stage order, relative duration, or visual flags.
